import React from 'react';

function Register() {
  // Handle Submit
  const handleSubmit = (e) => {
    e.preventDefault();
    alert('form');
  };
  // Handle Change
  const handleChange = (e) => {};
  // Return
  return (
    <>
      <form onSubmit={(e) => handleSubmit(e)}>
        {/* Logo and title */}
        <div className="logo">
          <img src="" alt="" />
          <h2>chaxapp</h2>
        </div>
        {/* User div */}
        <div className="input_div">
          <input
            type="text"
            name="username"
            onChange={(e) => handleChange(e)}
          />
          <label>username</label>
        </div>
        <div className="error_div"></div>
        {/* Mobile number div */}
        <div className="input_div">
          <input
            type="text"
            name="mobileNumber"
            onChange={(e) => handleChange(e)}
          />
          <label>Mobile number</label>
        </div>
        <div className="error_div"></div>
        {/* User div */}
        <div className="input_div">
          <input
            type="password"
            name="password"
            onChange={(e) => handleChange(e)}
          />
          <label>Password</label>
        </div>
        <div className="error_div"></div>
        {/* User div */}
        <div className="input_div">
          <input
            type="password"
            name="confirmPassword"
            onChange={(e) => handleChange(e)}
          />
          <label>Confirm Password</label>
        </div>
        <div className="error_div"></div>
        {/* Register buttom */}
        <button type="submit">Create account</button>
        {/* hrd */}
        <div className="or">
          <span></span>
          <p>OR</p>
          <span></span>
        </div>
        {/* login */}
        .login_
      </form>
    </>
  );
}

export default Register;
